import Foundation
import ProgramModel
import Testing

/// Brick backend slice 2: the math functions' semantics (ADR-046, brief D2).
///
/// **The table is Catroid's own output**, generated by running
/// `MathFunctionProvider`'s expressions (and its `interpretFunctionMod`,
/// verbatim) under Java 17 (desktop JDK, not Android ART) on 2026-10-17, so no
/// expected value here was computed by hand or by the code under test.
///
/// **Within 4 ulps, not 1e-9.** Java's and Darwin's libm may differ in the last
/// place (`exp(1)` is `2.7182818284590455` in Java), and a fixed absolute
/// tolerance is wrong at both ends: at `tan(90)` ≈ 1.6e16 one ulp is 2, and near
/// zero 1e-9 would let `sin(180)` snap to 0 (ADR-017; Codex brief review,
/// finding 5). A zero expectation is exact.
@Suite("Formula functions")
struct FormulaFunctionTests {
    private let scope = VariableScope()

    private func value(_ formula: Formula) throws -> Double {
        try formula.interpretDouble(scope: scope)
    }

    private func expect(
        _ actual: Double,
        of expected: Double,
        within ulps: Double = 4,
        sourceLocation: SourceLocation = #_sourceLocation
    ) {
        // A zero expectation is exact *including its sign*: `−0` is observable through
        // `arctan2` (both reviews of slice 2).
        let close = expected == 0
            ? actual == 0 && actual.sign == expected.sign
            : abs(actual - expected) <= ulps * expected.ulp
        #expect(close, "\(actual) is not within \(ulps) ulps of \(expected)", sourceLocation: sourceLocation)
    }

    @Test("every unary function matches Catroid's table", arguments: CatroidFunctionTable.unaryTable)
    func unaryMatchesCatroid(_ row: CatroidFunctionTable.UnaryRow) throws {
        expect(try value(.unaryFunction(row.function, .number(row.input))), of: row.expected)
    }

    @Test("every binary function matches Catroid's table", arguments: CatroidFunctionTable.binaryTable)
    func binaryMatchesCatroid(_ row: CatroidFunctionTable.BinaryRow) throws {
        let formula = Formula.binaryFunction(row.function, .number(row.first), .number(row.second))
        expect(try value(formula), of: row.expected)
    }

    @Test("the table covers every function")
    func tableCoversEveryFunction() {
        #expect(Set(CatroidFunctionTable.unaryTable.map(\.function)) == Set(UnaryFunction.allCases))
        // `power` has its own table beside the logic it joined with (Variables slice 1).
        let power: Set<BinaryFunction> = CatroidLogicTable.powerRows.isEmpty ? [] : [.power]
        #expect(Set(CatroidFunctionTable.binaryTable.map(\.function)).union(power) == Set(BinaryFunction.allCases))
    }

    @Test("pi is Math.PI exactly")
    func pi() throws {
        #expect(try value(.constant(.pi)) == 3.141592653589793)
    }

    // MARK: - Residuals pinned, not snapped

    /// Catroid's `sin(toRadians(180))` is not 0, and a design that feeds it to
    /// `floor` or a stitch count sees the difference. An exact-degree shortcut
    /// (`sinpi(x / 180)`) would snap it to 0.
    @Test("sin(180) keeps Catroid's residual")
    func sinResidual() throws {
        #expect(try value(.unaryFunction(.sin, .number(180))) == 1.2246467991473532e-16)
        #expect(try value(.unaryFunction(.cos, .number(90))) == 6.123233995736766e-17)
    }

    @Test("tan(90) is a large finite number, not infinity or zero")
    func tanNinety() throws {
        expect(try value(.unaryFunction(.tan, .number(90))), of: 1.633123935319537e16)
    }

    /// ADR-019: `log(1000)` is exactly 3 in both libms, and `floor` sits right on
    /// it, so the threshold is asserted directly rather than within ulps.
    @Test("floor(log(1000)) is 3 — an ADR-019 threshold")
    func logThreshold() throws {
        #expect(try value(.unaryFunction(.log, .number(1000))) == 3)
        #expect(try value(.unaryFunction(.floor, .unaryFunction(.log, .number(1000)))) == 3)
    }

    // MARK: - ADR-017: normalization and NaN

    @Test("results are normalized like every other node")
    func normalized() throws {
        #expect(try value(.unaryFunction(.exp, .number(1000))) == .greatestFiniteMagnitude)
        #expect(try value(.unaryFunction(.ln, .number(0))) == -.greatestFiniteMagnitude)
    }

    @Test("a NaN result at the root throws", arguments: [
        Formula.unaryFunction(.sqrt, .number(-1)),
        .unaryFunction(.arcsin, .number(2)),
        .unaryFunction(.ln, .number(-1))
    ])
    func nanThrows(_ formula: Formula) {
        #expect(throws: FormulaError.notANumber) { try formula.interpretDouble(scope: VariableScope()) }
    }

    /// Java `Math.max`/`min` return NaN when either argument is NaN; Swift's
    /// `max(.nan, 1)` is NaN but `max(1, .nan)` is 1, and `Double.maximum`
    /// drops the NaN — so both argument orders are pinned.
    @Test("min and max propagate NaN from either argument")
    func minMaxNaN() {
        let nan = Formula.unaryFunction(.sqrt, .number(-1))
        for function in [BinaryFunction.min, .max] {
            #expect(throws: FormulaError.notANumber) {
                try Formula.binaryFunction(function, nan, .number(1)).interpretDouble(scope: VariableScope())
            }
            #expect(throws: FormulaError.notANumber) {
                try Formula.binaryFunction(function, .number(1), nan).interpretDouble(scope: VariableScope())
            }
        }
    }

    @Test("min and max order signed zeros as Java does")
    func minMaxSignedZero() throws {
        #expect(try value(.binaryFunction(.min, .number(-0.0), .number(0))).sign == .minus)
        #expect(try value(.binaryFunction(.min, .number(0), .number(-0.0))).sign == .minus)
        #expect(try value(.binaryFunction(.max, .number(-0.0), .number(0))).sign == .plus)
        #expect(try value(.binaryFunction(.max, .number(0), .number(-0.0))).sign == .plus)
    }

    // MARK: - round: Java 7+ Math.round (brief D2, mirrored and divergence d)

    /// `Math.round(NaN)` is 0, so `round` consumes a NaN argument instead of
    /// letting it reach the root — mirrored (Codex brief review: consistent
    /// with ADR-017, which only throws for NaN at the root).
    @Test("round of NaN is 0")
    func roundNaN() throws {
        #expect(try value(.unaryFunction(.round, .unaryFunction(.sqrt, .number(-1)))) == 0)
    }

    /// Java returns a `long`, which has no negative zero.
    @Test("round never returns negative zero")
    func roundSignedZero() throws {
        #expect(try value(.unaryFunction(.round, .number(-0.5))).sign == .plus)
        #expect(try value(.unaryFunction(.round, .number(-0.0))).sign == .plus)
    }

    /// `Math.round` saturates at the `long` bounds; 2⁶³ itself is the first value
    /// that would trap `Int64(_:)` (`swift-code-reviewer`, slice 2).
    @Test("round saturates at the long bounds")
    func roundSaturates() throws {
        #expect(try value(.unaryFunction(.round, .number(9_223_372_036_854_775_808))) == 9.223372036854776e18)
        #expect(try value(.unaryFunction(.round, .number(-9_223_372_036_854_775_808))) == -9.223372036854776e18)
    }

    /// Divergence (d): the engine's `javaRound` is `floor(x + 0.5)`, which
    /// rounds both of these up; Java 7+ does not.
    @Test("round follows Java 7+, not floor(x + 0.5)")
    func roundJavaSeven() throws {
        #expect(try value(.unaryFunction(.round, .number(0.49999999999999994))) == 0)
        #expect(try value(.unaryFunction(.round, .number(4503599627370497))) == 4503599627370497)
        #expect(try value(.unaryFunction(.round, .number(-2.5))) == -2)
    }

    // MARK: - mod (divergence a)

    /// Catroid returns `(6 % −3) + (−3)` = −3 when the remainder is zero and
    /// the signs differ; the floored modulo it otherwise implements gives 0.
    @Test("6 mod −3 is 0, where Catroid gives −3")
    func modZeroRemainder() throws {
        #expect(try value(.binaryFunction(.mod, .number(6), .number(-3))) == 0)
    }

    /// Catroid's `while (dividend < 0) dividend += |divisor|` never ends once
    /// the addition no longer changes the dividend — a hang in Android.
    @Test("mod of a huge negative dividend terminates")
    func modTerminates() throws {
        #expect(try value(.binaryFunction(.mod, .number(-.greatestFiniteMagnitude), .number(1))) == 0)
        #expect(try value(.binaryFunction(.mod, .number(-1e300), .number(7))) >= 0)
    }

    /// Catroid reaches a zero remainder by repeated addition (`−6 + 3 + 3 = +0`)
    /// or by Java `%` (`−6 % −3 = −0`), so a zero result carries the divisor's
    /// sign. Observable: `arctan2(−0, −1)` is −180° where `arctan2(+0, −1)` is
    /// 180° (both reviews of slice 2).
    @Test("a zero remainder carries the divisor's sign, as in Catroid")
    func modZeroSign() throws {
        #expect(try value(.binaryFunction(.mod, .number(-6), .number(3))).sign == .plus)
        #expect(try value(.binaryFunction(.mod, .number(-6), .number(-3))).sign == .minus)
        #expect(try value(.binaryFunction(.mod, .number(6), .number(3))).sign == .plus)
        let angle = Formula.binaryFunction(.arctan2, .binaryFunction(.mod, .number(-6), .number(3)), .number(-1))
        #expect(try value(angle) == 180)
    }

    /// A tiny negative dividend: `−1e−14 + 360` rounds to 360 in Catroid's loop,
    /// and `360 % 360` is 0. A single `fmod` plus one correction returns 360, which
    /// is outside a modulo's range (`swift-code-reviewer`, slice 2).
    @Test("a result never equals the divisor")
    func modNeverReturnsTheDivisor() throws {
        #expect(try value(.binaryFunction(.mod, .number(-1e-14), .number(360))) == 0)
        #expect(try value(.binaryFunction(.mod, .number(-1e-17), .number(1))) == 0)
        #expect(try value(.binaryFunction(.mod, .unaryFunction(.sin, .number(360)), .number(360))) == 0)
    }

    /// Divergence (a), the rounding half: Catroid's repeated addition accumulates
    /// error for a negative dividend and a non-integral positive divisor, so
    /// `mod(−1, 0.1)` is 0.09999999999999987 there. The exact floored modulo is
    /// pinned here instead (Codex slice review of slice 2).
    @Test("mod is exact where Catroid's loop accumulates rounding")
    func modDoesNotAccumulate() throws {
        #expect(try value(.binaryFunction(.mod, .number(-1), .number(0.1))) == 5.551115123125783e-17)
    }

    /// Mirrored, not a divergence: `x mod 0` is `x` in Catroid.
    @Test("x mod 0 is x")
    func modByZero() throws {
        #expect(try value(.binaryFunction(.mod, .number(5), .number(0))) == 5)
        #expect(try value(.binaryFunction(.mod, .number(-5), .number(-0.0))) == -5)
    }

    // MARK: - arctan2 (divergence b)

    /// Catroid returns a random angle for (0, 0). Zero instead, and the
    /// `(+0, −0)` case pins that the special case exists at all: raw IEEE
    /// `atan2(+0, −0)` is 180° (Codex brief review, finding 5).
    @Test("arctan2 of two zeros is 0, whatever their signs")
    func arctanTwoZeros() throws {
        #expect(try value(.binaryFunction(.arctan2, .number(0), .number(0))) == 0)
        #expect(try value(.binaryFunction(.arctan2, .number(0), .number(-0.0))) == 0)
        #expect(try value(.binaryFunction(.arctan2, .number(-0.0), .number(-0.0))) == 0)
    }

    @Test("arctan2 takes y first, as Catroid does")
    func arctanArgumentOrder() throws {
        #expect(try value(.binaryFunction(.arctan2, .number(1), .number(0))) == 90)
        #expect(try value(.binaryFunction(.arctan2, .number(0), .number(1))) == 0)
    }

    // MARK: - Totality (acceptance criterion: no trap, no hang)

    /// A deterministic generator, so a failure reproduces from its seed.
    private struct SplitMix: RandomNumberGenerator {
        var state: UInt64
        mutating func next() -> UInt64 {
            state &+= 0x9E37_79B9_7F4A_7C15
            var mixed = state
            mixed = (mixed ^ (mixed >> 30)) &* 0xBF58_476D_1CE4_E5B9
            mixed = (mixed ^ (mixed >> 27)) &* 0x94D0_49BB_1331_11EB
            return mixed ^ (mixed >> 31)
        }
    }

    private static let extremes: [Double] = [
        0, -0.0, 1, -1, 0.5, 90, 180, -360, 1e-300, -1e-300, 1e300, -1e300,
        .greatestFiniteMagnitude, -.greatestFiniteMagnitude, .infinity, -.infinity, .nan
    ]

    private static func tree(depth: Int, using rng: inout SplitMix) -> Formula {
        if depth == 0 || rng.next() % 4 == 0 {
            return rng.next() % 5 == 0 ? .constant(.pi) : .number(extremes.randomElement(using: &rng) ?? 0)
        }
        if rng.next() % 2 == 0 {
            let function = UnaryFunction.allCases.randomElement(using: &rng) ?? .sin
            return .unaryFunction(function, tree(depth: depth - 1, using: &rng))
        }
        let function = BinaryFunction.allCases.randomElement(using: &rng) ?? .mod
        return .binaryFunction(function, tree(depth: depth - 1, using: &rng), tree(depth: depth - 1, using: &rng))
    }

    /// 5 000 trees up to 6 deep over every function and the extreme leaves:
    /// each evaluates to a finite value or throws `notANumber` — never traps,
    /// never hangs (`mod(-MAX, 1)` hangs Catroid), never returns ±∞.
    @Test("no function tree traps, hangs or returns infinity")
    func totality() {
        var rng = SplitMix(state: 0x2026_1017)
        for _ in 0 ..< 5000 {
            let formula = Self.tree(depth: 6, using: &rng)
            do {
                let result = try formula.interpretDouble(scope: VariableScope())
                #expect(result.isFinite, "\(formula) gave \(result)")
            } catch {
                #expect(error as? FormulaError == .notANumber, "\(formula) threw \(error)")
            }
        }
    }
}

/// Catroid's own output for `MathFunctionProvider` (and its `interpretFunctionMod`,
