/// the suite reads as the claims it makes.
enum CatroidFunctionTable {
    struct UnaryRow: Sendable {
        let function: UnaryFunction, input: Double, expected: Double
        init(_ function: UnaryFunction, _ input: Double, _ expected: Double) {
            (self.function, self.input, self.expected) = (function, input, expected)
        }
    }

    struct BinaryRow: Sendable {
        let function: BinaryFunction, first: Double, second: Double, expected: Double
        init(_ function: BinaryFunction, _ first: Double, _ second: Double, _ expected: Double) {
            (self.function, self.first, self.second, self.expected) = (function, first, second, expected)
        }
